    "anchors.d.ts": "/** A rectangle in the layer, CSS pixels from its top left. */\nexport interface Box {\n    x: number;\n    y: number;\n    width: number;\n    height: number;\n}\n/** Where a thing an annotation points at is now. */\nexport interface Anchor {\n    /** Its outline on screen; a point is a box of no size. */\n    box: Box;\n    /** In front of the eye and inside the view. */\n    visible: boolean;\n    /** Something drawn stands between the eye and it. */\n    occluded?: boolean;\n}\nexport interface Anchors {\n    get: (id: string) => Anchor | undefined;\n    /** Calls `listener` after each commit. */\n    subscribe: (listener: () => void) => () => void;\n}\nexport interface AnchorStore extends Anchors {\n    set: (id: string, anchor: Anchor | undefined) => void;\n    /** Tells readers that this frame's anchors are written. */\n    commit: () => void;\n}\n/** A store a renderer fills: `set` each anchor, then `commit` once a frame. */\nexport declare function anchorStore(): AnchorStore;\n/** The smallest box holding every point. */\nexport declare function boxAround(points: Iterable<readonly [number, number]>): Box;\n",
    "annotation.d.ts": "import type { HTMLAttributes, ReactNode } from 'react';\nimport type { Connector, Subject } from './paths';\nimport type { Placement } from './place';\nexport interface AnnotationProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {\n    /** The id the renderer writes this subject's anchor under. */\n    anchor: string;\n    /** How the subject is marked; a function draws it from its box. */\n    subject?: Subject;\n    /** How the note is joined to it; a function draws it from its two ends. */\n    connector?: Connector;\n    /** The sides the note may take, tried in this order. */\n    placements?: ReadonlyArray<Placement>;\n    /** Space between the subject and the note, in pixels. */\n    gap?: number;\n    /** Space between the subject and its mark, in pixels. */\n    padding?: number;\n    /** Higher places first and keeps its side when notes compete. */\n    priority?: number;\n    /** Stays shown when its subject leaves the view, at the nearest edge. */\n    pinned?: boolean;\n    /** Hides rather than cover a reserved control or a note of higher priority: for labels. */\n    yields?: boolean;\n    children?: ReactNode;\n}\n/** A note attached to a subject the renderer projects. Holds any children. */\nexport declare function Annotation({ anchor, subject, connector, placements, gap, padding, priority, pinned, yields, children, className, style, ...slot }: AnnotationProps): import(\"react\").JSX.Element | null;\n",
