    "index.d.ts": "import '@astryxdesign/core/astryx.css';\nimport '@astryxdesign/theme-neutral/theme.css';\nexport { anchorStore, boxAround } from './anchors';\nexport type { Anchor, AnchorStore, Anchors, Box } from './anchors';\nexport { Annotation } from './annotation';\nexport type { AnnotationProps } from './annotation';\nexport { useAnchor } from './hooks';\nexport { AnnotationLayer, KeepClear, PLACEMENTS } from './layer';\nexport type { AnnotationLayerProps } from './layer';\nexport { Label, Note } from './note';\nexport type { LabelProps, NoteProps } from './note';\nexport { connectorEnds, connectorPath, subjectPath } from './paths';\nexport type { Connector, Point, Subject } from './paths';\nexport { choose, cost, nearest, overlap } from './place';\nexport type { Candidate, Placement, PlaceOptions } from './place';\nexport { Theme } from './theme';\n",
    "layer.d.ts": "import type { HTMLAttributes, ReactNode } from 'react';\nimport type { Anchors, Box } from './anchors';\nimport type { Connector, Subject } from './paths';\nimport type { Placement } from './place';\n/** One annotation as the layer places it. */\nexport interface Entry {\n    anchor: string;\n    subject: Subject;\n    connector: Connector;\n    placements: ReadonlyArray<Placement>;\n    gap: number;\n    padding: number;\n    priority: number;\n    pinned: boolean;\n    /** Hidden, not placed, where it would cover a reserved control or a note placed before it. */\n    yields: boolean;\n    slot: HTMLDivElement | null;\n    subjectPath: SVGPathElement | null;\n    connectorPath: SVGPathElement | null;\n    size: {\n        width: number;\n        height: number;\n    };\n    previous?: Placement;\n    /** Where the note was put last, in the layer. */\n    placed?: Box;\n}\ninterface LayerContext {\n    register: (entry: Entry) => () => void;\n    keepClear: (element: Element) => () => void;\n    schedule: () => void;\n    notes: HTMLDivElement | null;\n    svg: SVGSVGElement | null;\n}\nexport declare function useLayer(): LayerContext;\nexport declare const PLACEMENTS: ReadonlyArray<Placement>;\nexport interface AnnotationLayerProps extends HTMLAttributes<HTMLDivElement> {\n    /** Where each subject is now; the layer places its notes on every commit. */\n    anchors: Anchors;\n    /** Space a note keeps from the layer's edge, in pixels. */\n    margin?: number;\n    children?: ReactNode;\n}\n/**\n * The layer notes live in: an SVG for subjects and leaders, and a plane for\n * the notes. It covers its positioned parent and lets pointer events through\n * except on the notes themselves.\n */\nexport declare function AnnotationLayer({ anchors, margin, children, className, style, ...rest }: AnnotationLayerProps): import(\"react\").JSX.Element;\n/** Keeps every note off its children: wrap controls that sit over the scene. */\nexport declare function KeepClear({ children, ...rest }: HTMLAttributes<HTMLDivElement>): import(\"react\").JSX.Element;\nexport {};\n",
