    "paths.d.ts": "import type { Box } from './anchors';\nexport type Point = [number, number];\n/** What is marked: a built-in shape, or a function from the subject's box to path data. */\nexport type Subject = 'none' | 'point' | 'circle' | 'rect' | 'bracket' | ((box: Box) => string);\n/** How the note is joined to its subject: a built-in leader, or a function from its ends to path data. */\nexport type Connector = 'none' | 'line' | 'elbow' | 'curve' | ((from: Point, to: Point) => string);\n/** The subject's outline as path data, `padding` outside its box. */\nexport declare function subjectPath(subject: Subject, box: Box, padding?: number): string;\n/**\n * Where a leader starts on the subject (its padded outline, on the side\n * facing the note) and where it meets the note (the note's nearest point).\n */\nexport declare function connectorEnds(subject: Box, note: Box, padding?: number): {\n    from: Point;\n    to: Point;\n};\n/** The leader as path data. */\nexport declare function connectorPath(connector: Connector, from: Point, to: Point): string;\n",
    "place.d.ts": "import type { Box } from './anchors';\nexport type Placement = 'top' | 'top-start' | 'top-end' | 'right' | 'right-start' | 'right-end' | 'bottom' | 'bottom-start' | 'bottom-end' | 'left' | 'left-start' | 'left-end';\nexport interface Candidate {\n    placement: Placement;\n    box: Box;\n}\nexport interface PlaceOptions {\n    /** What the note is about; covering it is costly. */\n    subject: Box;\n    /** Other notes, subjects and controls to keep clear of. */\n    obstacles: ReadonlyArray<Box>;\n    /** The layer; a note out of it is costly. */\n    bounds: Box;\n    /** The placement chosen last frame, kept unless another is clearly better. */\n    previous?: Placement;\n}\n/** The area two boxes share. */\nexport declare function overlap(a: Box, b: Box): number;\n/** The point of `box` nearest to (x, y). */\nexport declare function nearest(box: Box, x: number, y: number): [number, number];\n/**\n * What a candidate costs: lower is better. An overlap costs by the share of\n * the smaller box it hides, so a note over a small part or label costs as much\n * as over a large one; hiding its own subject outweighs hiding anything else.\n * Leaving the layer is measured against the note, and a longer leader costs a\n * little.\n */\nexport declare function cost(candidate: Candidate, options: PlaceOptions): number;\n/**\n * The candidate to use: the cheapest, the previous one given a small head start\n * so a note does not flicker between two near-equal sides. The head start is\n * added, not multiplied, so it never holds a note somewhere clearly worse.\n */\nexport declare function choose(candidates: ReadonlyArray<Candidate>, options: PlaceOptions): Candidate;\n",
